AssistantMessageToolRequest(name='create', tool_call_id='toolu_01F5guQX1UK6wubdqFg2nBpN', arguments={'path': '/workspace/sandbox/skills/building-accessible-ui/checkbox-group--framework-vanilla-js--style-modern/claude-opus-4.7__s1/script.js', 'file_text': '(function () {
  const form = document.getElementById('quiz');
  const result = document.getElementById('result');
  if (!form) return;

  const questionNames = ['q1', 'q2', 'q3'];

  function gradeQuestion(name) {
    const inputs = form.querySelectorAll(`input[name="${name}"]`);
    let correct = true;
    inputs.forEach((input) => {
      const shouldBeChecked = input.dataset.correct === 'true';
      if (input.checked !== shouldBeChecked) correct = false;
    });
    return correct;
  }

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    let score = 0;
    const perQuestion = questionNames.map((name, i) => {
      const ok = gradeQuestion(name);
      if (ok) score++;
      return { num: i + 1, ok };
    });

    const total = questionNames.length;
    const isPerfect = score === total;
    result.classList.toggle('is-perfect', isPerfect);

    const items = perQuestion
      .map((q) => `<li>Question ${q.num}: ${q.ok ? 'Correct' : 'Not quite'}</li>`)
      .join('');

    result.innerHTML = `
      <h2>You scored <span class="score">${score} of ${total}</span></h2>
      <ul>${items}</ul>
    `;
    result.focus?.();
  });

  form.addEventListener('reset', () => {
    result.className = 'result';
    result.innerHTML = '';
  });
})();
